/**
 * iOS 侧 LIVE 徽章矢量：与 Android drawable `ic_post_live_badge` 完全一致，
 * 由该 VectorDrawable 的 pathData 转换而来（避免 iOS 上回退成 "LIVE" 文字徽章）。
 *
 * Android 侧仍用 R.drawable.ic_post_live_badge（同一份视觉来源），两端视觉对齐。
 */
internal val FoxLiveBadgeVector: ImageVector by lazy {
    ImageVector.Builder(
        defaultWidth = 20.dp,
        defaultHeight = 20.dp,
        viewportWidth = 1024f,
        viewportHeight = 1024f,
    ).apply {
        addPath(
            pathData = PathParser().parsePathString(PATH_DATA).toNodes().toList(),
            fill = SolidColor(Color(0xFFFFFFFF)),
        )
    }.build()
}

